//! 🧪️ Paid original Work and physical actions for terminal handoff laws.
use super::source_bank;
use semio_framework_value_control_contract::*;
use semio_framework_value_native_decoding::{NativeDecodeFrame,NativeDecodeRetirementRecipient};
use semio_framework_value_native_decode_handoff::NativeDecodeFrameHandoff;
#[derive(Default)]
pub(crate) struct PaidAction{pub(crate) physical:Option<OriginalConstructionAction>,pub(crate) work:Option<OriginalWorkActionIdentity>,pub(crate) receipt:Option<OriginalWorkPerformedReceipt>,pub(crate) claim:Option<Result<u128,ValueError>>,pub(crate) maximum_work:u64,pub(crate) charged:u128,pub(crate) partial:Option<OriginalWorkPartialOutcome>,pub(crate) proof:Option<OriginalWorkActionProof>,pub(crate) actual:Option<usize>,pub(crate) progress:Option<RetainedCloneProgress>}
impl PaidAction{
 pub(crate) fn begin(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,previous:Option<OriginalConstructionActionIdentity>,demand:RetirementDemand,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){self.begin_units(bank,frame,recipient,previous,demand,1,observe)}
 pub(crate) fn begin_units(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,previous:Option<OriginalConstructionActionIdentity>,demand:RetirementDemand,units:u64,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){self.begin_mode(bank,frame,recipient,previous,demand,units,true,observe)}
 pub(crate) fn begin_guarded(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,previous:Option<OriginalConstructionActionIdentity>,demand:RetirementDemand,units:u64,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){self.begin_mode(bank,frame,recipient,previous,demand,units,false,observe)}
 pub(crate) fn begin_mode(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,previous:Option<OriginalConstructionActionIdentity>,demand:RetirementDemand,units:u64,issue:bool,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){self.maximum_work=units;bank.with_terminal_loans(|work,physical|{frame.begin_terminal_action(previous,recipient,work,physical,&mut self.physical,demand,observe).unwrap();let ready=frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,physical,payout|{assert_eq!(work.prepare(self.maximum_work,&mut self.work)?,Some(true));physical.quote(payout.as_mut().unwrap())?;let grant=physical.recover_grant(payout.as_mut().unwrap())?.unwrap()?;if !retained_clone_grant_admits(grant,demand){physical.cancel(payout.as_mut().unwrap(),false,Default::default(),None)?;work.cancel(&mut self.work)?;return Ok(false)}if issue{work.issue_performed(self.work,&mut self.receipt)?}Ok::<_,ValueError>(true)}).unwrap();if !ready{frame.finish_terminal_cancelled(physical,&mut self.physical)?;return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original finite Source denied retirement demand"))}Ok(())}).unwrap_or_else(|error|{let wallet=bank.wallet.lock().unwrap();panic!("original retirement demand {demand:?} refused with remaining {:?}, fuel {}: {error:?}",wallet.left,wallet.fuel)})}
 pub(crate) fn copy(&mut self,source:&mut Option<u64>,output:&mut Option<u64>){let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut self.actual,self.receipt.as_mut().unwrap());assert!(effect.performed(1).unwrap());assert!(output.is_none());*output=source.take();self.progress=Some(RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<u64>(),..Default::default()})}
 pub(crate) fn capture(&mut self,bank:&mut source_bank::Bank,source:&mut Option<OriginalConstructionAction>,output:&mut Option<OriginalConstructionCompletion>){bank.with_terminal_loans(|_,physical|{let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut self.actual,self.receipt.as_mut().unwrap());let witness=physical.witness(self.physical.as_ref().unwrap())?;self.progress=physical.stage_completion(source,output,&witness,&mut effect).result?.or_else(||panic!("funded original capture denied"));Ok(())}).unwrap()}
 pub(crate) fn restage(&mut self,bank:&mut source_bank::Bank,source:&mut Option<OriginalConstructionCompletion>,output:&mut Option<OriginalConstructionCompletion>,refusal:&OriginalConstructionCompletion){bank.with_terminal_loans(|_,physical|{let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut self.actual,self.receipt.as_mut().unwrap());let witness=physical.witness(self.physical.as_ref().unwrap())?;self.progress=physical.restage_completion(source,output,refusal,&witness,&mut effect).result?.or_else(||panic!("funded retry denied"));Ok(())}).unwrap()}
 pub(crate) fn retire(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,completion:&mut Option<OriginalConstructionCompletion>,parent:bool){bank.with_terminal_loans(|_,physical|{let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut self.actual,self.receipt.as_mut().unwrap());let result=if parent{frame.retire_terminal_completion(completion,physical,self.physical.as_ref().unwrap(),&mut effect)}else{physical.retire_completion(completion,self.physical.as_ref().unwrap(),&mut effect)};self.progress=result.result?.or_else(||panic!("funded retirement denied"));Ok(())}).unwrap()}
 pub(crate) fn post(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool)->OriginalConstructionAcceptStatus{self.post_optional(bank,frame,recipient,observe).expect("original effect was performed")}
 pub(crate) fn post_optional(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool)->Option<OriginalConstructionAcceptStatus>{bank.with_terminal_loans(|work,physical|{if self.proof.is_none(){frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,_,_|{if let Some(claim)=self.claim.take(){claim?;}else{work.claim_performed(self.work,&mut self.receipt)?;}if work.partial_pending(self.work)?{assert!(work.settle_partial_into(self.work,&mut self.partial)?);assert!(self.partial.as_ref().unwrap().source_refusal().is_none());drop(self.partial.take())}let actual=work.performed_total(self.work)?;self.charged=actual;assert!(work.commit(actual,self.work,&mut self.proof)?);Ok::<_,ValueError>(())}).unwrap()}let action=self.physical.as_mut().unwrap();if action.phase()==OriginalConstructionPhase::Granted{if self.charged==0&&self.actual.is_none()&&self.progress==Some(Default::default()){physical.cancel(action,false,Default::default(),None)?;return Ok(None)}physical.post(action,self.progress.unwrap(),self.actual)?}if action.phase()==OriginalConstructionPhase::Settled{return Ok(action.recorded_accept_status())}Ok(physical.recover_accept(action)?)}).unwrap()}
 pub(crate) fn publish(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,completion:&mut Option<OriginalConstructionCompletion>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,physical,payout|{assert!(physical.publish_completion(completion.as_mut().unwrap(),payout.as_mut().unwrap(),work,self.proof.as_ref().unwrap())?);Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap()}
 pub(crate) fn finish_work(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{frame.with_terminal_work(recipient,work,physical,&mut self.physical,observe,|work,_,_|work.finish(&mut self.proof,&mut self.work)).unwrap();Ok(())}).unwrap()}
 pub(crate) fn finish(&mut self,bank:&mut source_bank::Bank,frame:&mut NativeDecodeFrame,recipient:&mut NativeDecodeRetirementRecipient,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){self.finish_work(bank,frame,recipient,observe);bank.with_terminal_loans(|_,physical|{if self.physical.as_ref().unwrap().recorded_accept_status()==Some(OriginalConstructionAcceptStatus::Accepted){frame.finish_terminal_child(physical,&mut self.physical)}else{frame.finish_terminal_cancelled(physical,&mut self.physical)}}).unwrap()}
}

impl PaidAction{
 pub(crate) fn prepare_handoff(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){self.maximum_work=1;bank.with_terminal_loans(|work,physical|{handoff.with_receipt_payout(work,physical,&mut self.physical,observe,|work,physical,payout|{assert_eq!(work.prepare(1,&mut self.work)?,Some(true));physical.quote(payout.as_mut().unwrap())?;assert!(physical.recover_grant(payout.as_mut().unwrap())?.unwrap().is_ok());work.issue_performed(self.work,&mut self.receipt)?;Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap()}
 pub(crate) fn begin_handoff_initial(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{handoff.begin_receipt_payout(work,physical,&mut self.physical,OriginalConstructionCompletion::demand(),observe).unwrap();Ok(())}).unwrap();self.prepare_handoff(bank,handoff,observe)}
 pub(crate) fn begin_handoff_primary(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,completion:&OriginalConstructionCompletion,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{handoff.begin_published_receipt_payout(completion,work,physical,&mut self.physical,observe).unwrap();Ok(())}).unwrap();self.prepare_handoff(bank,handoff,observe)}
 pub(crate) fn begin_handoff_capture(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,rejected:&OriginalConstructionAction,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{handoff.begin_receipt_refusal_capture(rejected,work,physical,&mut self.physical,observe).unwrap();Ok(())}).unwrap();self.prepare_handoff(bank,handoff,observe)}
 pub(crate) fn begin_handoff_retry(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,refusal:&OriginalConstructionCompletion,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{handoff.begin_receipt_retry(refusal,work,physical,&mut self.physical,observe).unwrap();Ok(())}).unwrap();self.prepare_handoff(bank,handoff,observe)}
 pub(crate) fn stage_handoff_original(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,completion:&mut Option<OriginalConstructionCompletion>){bank.with_terminal_loans(|_,physical|{let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut self.actual,self.receipt.as_mut().unwrap());self.progress=handoff.stage_receipt_completion(physical,self.physical.as_ref().unwrap(),completion,&mut effect).result?;Ok(())}).unwrap();assert!(self.progress.is_some())}
 pub(crate) fn stage_handoff_primary(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,completion:&mut Option<OriginalConstructionCompletion>){bank.with_terminal_loans(|_,physical|{let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut self.actual,self.receipt.as_mut().unwrap());self.progress=handoff.stage_receipt_primary(completion,physical,self.physical.as_ref().unwrap(),&mut effect).result?;Ok(())}).unwrap();assert!(self.progress.is_some())}
 pub(crate) fn stage_handoff_capture(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,rejected:&mut Option<OriginalConstructionAction>,refusal:&mut Option<OriginalConstructionCompletion>){bank.with_terminal_loans(|_,physical|{let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut self.actual,self.receipt.as_mut().unwrap());self.progress=handoff.stage_receipt_refusal(rejected,physical,self.physical.as_ref().unwrap(),refusal,&mut effect).result?;Ok(())}).unwrap();assert!(self.progress.is_some())}
 pub(crate) fn stage_handoff_retry(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,refusal:&OriginalConstructionCompletion){bank.with_terminal_loans(|_,physical|{let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut self.actual,self.receipt.as_mut().unwrap());self.progress=handoff.stage_receipt_retry(refusal,physical,self.physical.as_ref().unwrap(),&mut effect).result?;Ok(())}).unwrap();assert!(self.progress.is_some())}
 pub(crate) fn post_handoff(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool)->OriginalConstructionAcceptStatus{bank.with_terminal_loans(|work,physical|{if self.proof.is_none(){handoff.with_receipt_payout(work,physical,&mut self.physical,observe,|work,_,_|{work.claim_performed(self.work,&mut self.receipt)?;assert!(work.settle_partial_into(self.work,&mut self.partial)?);assert!(self.partial.as_ref().unwrap().source_refusal().is_none());drop(self.partial.take());assert!(work.commit(1,self.work,&mut self.proof)?);Ok::<_,ValueError>(())}).unwrap()}let action=self.physical.as_mut().unwrap();if action.phase()==OriginalConstructionPhase::Granted{physical.post(action,self.progress.unwrap(),self.actual)?}Ok(physical.recover_accept(action)?.unwrap())}).unwrap()}
 pub(crate) fn publish_handoff_completion(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,completion:&mut Option<OriginalConstructionCompletion>,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{handoff.with_receipt_payout(work,physical,&mut self.physical,observe,|work,physical,payout|{assert!(physical.publish_completion(completion.as_mut().unwrap(),payout.as_mut().unwrap(),work,self.proof.as_ref().unwrap())?);Ok::<_,ValueError>(())}).unwrap();Ok(())}).unwrap()}
 pub(crate) fn publish_handoff_primary(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{assert!(handoff.publish_receipt_primary(work,physical,&mut self.physical,self.proof.as_ref().unwrap(),observe).unwrap());Ok(())}).unwrap()}
 pub(crate) fn finish_handoff_work(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){bank.with_terminal_loans(|work,physical|{handoff.with_receipt_payout(work,physical,&mut self.physical,observe,|work,_,_|work.finish(&mut self.proof,&mut self.work)).unwrap();Ok(())}).unwrap()}
 pub(crate) fn finish_handoff(&mut self,bank:&mut source_bank::Bank,handoff:&mut NativeDecodeFrameHandoff,observe:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool){self.finish_handoff_work(bank,handoff,observe);bank.with_terminal_loans(|_,physical|handoff.finish_receipt_payout(physical,&mut self.physical)).unwrap()}
}

